                (h - 1 - r, c),
                (c, r),
                (h - 1 - r, w - 1 - c),
                (w - 1 - c, h - 1 - r),
            ]
            for rr, cc in candidates:
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 2:
                    out[r][c] = grid[rr][cc]
                    break
    return out
